python3 - <<'EOF'
import json
d=json.load(open('analysis/apuracao_2026/dados/fiscais.json'))
secs=d['secoes']
# one best example per criterion: highest nivel, exige_explicacao_documental, has votes, prefer fewer criteria so numbers are clean
order={'alta':0,'media':1,'baixa':2}
for c in 'abcdefghijkl':
    cands=[s for s in secs if c in s['criterios'] and not s['sem_boletim'] and s['grupo_explicacao']=='exige_explicacao_documental']
    cands.sort(key=lambda s:(order[s['nivel']], -s['pontuacao'], -(s['votantes'] or 0)))
    print('=== critério',c, len(cands))
    for s in cands[:3]:
        keep={k:s[k] for k in ('uf','municipio','zona','secao','local','bairro','aptos','votantes','validos','brancos','nulos','lula','flavio','lula_pct','flavio_pct','zona_lula_pct','zona_flavio_pct','uf_lula_pct','uf_flavio_pct','encerramento_brasilia','recebido_tse','tipo_urna','tipo_arquivo','n_cargas','lula_2022_pct','flavio_2022_pct','criterios','nivel','pontuacao','explicacao_provavel')}
        keep['detalhe']=s['detalhe'].get(c)
        print(json.dumps(keep,ensure_ascii=False))
# h sem arquivo
print('=== h sem arquivo'); 
for s in d['sem_arquivo'][:3]: print(json.dumps({k:s[k] for k in ('uf','municipio','zona','secao','local','aptos','criterios','nivel')},ensure_ascii=False))
print('=== zonas congeladas'); print(json.dumps(d['zonas_congeladas'][:3],ensure_ascii=False)[:1500])
print('=== por_municipio top'); 
for m in d['prioridade_pl']['geral']['municipios'][:8]: print(json.dumps(m,ensure_ascii=False))
EOF

