import { Composition } from "remotion";
import { CaptionAIPromo } from "./CaptionAIVideo";
import { AmigoVideo } from "./scenes/amigo/AmigoVideo";
import { RelentlessVideo } from "./scenes/relentless/RelentlessVideo";

const FPS = 30;
const SCENE_DURATIONS_FRAMES = {
  intro: Math.round(3.5 * FPS),
  app1: Math.round(3.5 * FPS),
  speed: Math.round(3.5 * FPS),
  app2: Math.round(3.5 * FPS),
  platforms: 4 * FPS,
  cta: 4 * FPS,
};
const TOTAL = Object.values(SCENE_DURATIONS_FRAMES).reduce((a, b) => a + b, 0);

const AMIGO_FPS = 25;
const AMIGO_TOTAL = 750; // 5 scenes x 150 frames = 30s @ 25fps

const RELENTLESS_FPS = 25;
const RELENTLESS_TOTAL = 750;

export const RemotionRoot: React.FC = () => {
  return (
    <>
      <Composition
        id="CaptionAIPromo"
        component={CaptionAIPromo}
        durationInFrames={TOTAL}
        fps={FPS}
        width={1080}
        height={1920}
      />
      <Composition
        id="AmigoVideo"
        component={AmigoVideo}
        durationInFrames={AMIGO_TOTAL}
        fps={AMIGO_FPS}
        width={1080}
        height={1920}
      />
      <Composition
        id="RelentlessVideo"
        component={RelentlessVideo}
        durationInFrames={RELENTLESS_TOTAL}
        fps={RELENTLESS_FPS}
        width={1080}
        height={1920}
      />
    </>
  );
};
import { Config } from "@remotion/cli/config";

Config.setVideoImageFormat("jpeg");
Config.setOverwriteOutput(true);
Config.setPublicDir("./src/public");
{
  "compilerOptions": {
    "target": "ES2020",
    "module": "ESNext",
    "moduleResolution": "bundler",
    "jsx": "react",
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true
  },
  "include": ["src/**/*", "remotion.config.ts"]
}
