        legenda: `${inteiro(dados.sem_arquivo_por_zona.reduce((s, z) => s + z.secoes, 0))} seções sem arquivo publicado: ${sem}`,
        cor: COR.alta,
      };
    }
    case "i":
      return {
        valor: num(det.excesso_uf_lula_pp),
        casas: 1,
        prefixo: "+",
        sufixo: " pp",
