  const palavras = cena.palavras;
  const qCartao = quadro(palavras, g.cartao, 5);
  const iCartao = palavras.findIndex((p) => Math.round(p.t * 30) === qCartao);
  const qNumero = quadroDa(palavras, g.numero, Math.max(0, iCartao)) ?? qCartao + 90;
  const iNumero = palavras.findIndex((p) => Math.round(p.t * 30) === qNumero);
  const qConferir = quadroDa(palavras, g.conferir, Math.max(0, iNumero)) ?? Math.round(cena.segundos * 0.72 * 30);
  const d = destaque(criterio, dados);
  const topo = vertical ? 170 : 150;
  const base = vertical ? altura * 0.16 + 150 : 240;
  const mapaTamanho = vertical ? 300 : 300;

  const cabecalho = (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
      <Entrada inicio={0} de="esquerda">
        <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
          <Chip cor={COR.ouro} solido tamanho={vertical ? 20 : 22}>
