/** Fecho: as duas ações, os dois links, a marca e a última frase. */
export const Fecho: React.FC<{ cena: Cena }> = ({ cena }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const { vertical, margem } = useFormato();
