  if (existsSync(BINARIO)) {
    return BINARIO;
  }
  if (existsSync(zip)) {
    rmSync(pasta, { recursive: true, force: true });
    mkdirSync(pasta, { recursive: true });
    execFileSync("unzip", ["-q", zip], { cwd: pasta, stdio: "inherit" });
    if (existsSync(BINARIO)) {
      return BINARIO;
    }
  }
  if (existsSync(CHROME)) {
    return CHROME;
  }
  return null;
};

